service.method:

UPDATE
	USERVICE
SET
	  COMPANY_NAME = ${COMPANY_NAME}
	, SERVICE_FROM = ${SERVICE_FROM}
	, SERVICE_TO = ${SERVICE_TO}
	, CHANGE_USER_ID = ${session.ID}
	, CHANGE_DATE = ${current.DATE}
	, CHANGE_TIME = ${current.TIME}
WHERE
	HOUSE_CODE = ${CLIENT_CODE}
AND COMPANY_CODE = '1000'


INSERT INTO USERVICE
(
	  HOUSE_CODE
	, COMPANY_CODE
	, COMPANY_NAME
	, IRS_NO
	, SERVICE_FROM
	, SERVICE_TO
	, ADD_USER_ID
	, ADD_DATE
	, ADD_TIME
	, CHANGE_USER_ID
	, CHANGE_DATE
	, CHANGE_TIME
	, DEL_FLAG
)
VALUES
(
	  ${CLIENT_CODE}
	, ${COMPANY_CODE}
	, ${COMPANY_NAME}
	, ${IRS_NO}
	, ${SERVICE_FROM}
	, ${SERVICE_TO}
	, ${session.ID}
	, ${current.DATE}
	, ${current.TIME}
	, ${session.ID}
	, ${current.DATE}
	, ${current.TIME}
	, 'N'
)


INSERT INTO UCONF
(
	  HOUSE_CODE
	, COMPANY_CODE
	, `KEY`
	, VALUE
	, `GROUP`
	, ADD_USER_ID
	, ADD_DATE
	, ADD_TIME
	, CHANGE_USER_ID
	, CHANGE_DATE
	, CHANGE_TIME
	, DEL_FLAG
)
VALUES
(
	  ${HOUSE_CODE}
	, ${COMPANY_CODE}
	, ${KEY}
	, ${VALUE}
	, ${GROUP}
	, ${session.ID}
	, ${current.DATE}
	, ${current.TIME}
	, ${session.ID}
	, ${current.DATE}
	, ${current.TIME}
	, 'N'
)


INSERT INTO UPUSO
(
	  HOUSE_CODE
	, CODE
	, `TYPE`
	, OPTION_NAME
	, OPTION_VALUE
	, ADD_DATE
	, ADD_TIME
	, ADD_USER_ID
	, CHANGE_DATE
	, CHANGE_TIME
	, CHANGE_USER_ID
)
VALUES
(
	  ${HOUSE_CODE}
	, ${CODE}
	, ${TYPE}
	, ${OPTION_NAME}
	, ${OPTION_VALUE}
	, ${current.DATE}
	, ${current.TIME}
	, ${session.ID}
	, ${current.DATE}
	, ${current.TIME}
	, ${session.ID}
)


INSERT INTO SFFDT
(
	  HOUSE_CODE
	, FORM_ID
	, BLOCK_NAME
	, BLOCK_TYPE
	, REQUIRED
	, INPUT_WIDTH
	, ADD_USER_ID
	, ADD_DATE
	, ADD_TIME
	, CHANGE_USER_ID
	, CHANGE_DATE
	, CHANGE_TIME
)
VALUES
(
	  ${HOUSE_CODE}
	, ${FORM_ID}
	, ${BLOCK_NAME}
	, ${BLOCK_TYPE}
	, ${REQUIRED}
	, ${INPUT_WIDTH}
	, ${session.ID}
	, ${current.DATE}
	, ${current.TIME}
	, ${session.ID}
	, ${current.DATE}
	, ${current.TIME}
)


INSERT INTO SGRFT
(
	  HOUSE_CODE
	, GRID_ID
	, CODE
	, COL_TYPE
	, NOT_NULL
	, COL_FORMAT
	, COL_ALIGN
	, COL_SORT
	, COL_COLOR
	, COL_SEQ
	, ADD_USER_ID
	, ADD_DATE
	, ADD_TIME
	, CHANGE_USER_ID
	, CHANGE_DATE
	, CHANGE_TIME
)
VALUES
(
	  ${HOUSE_CODE}
	, ${GRID_ID}
	, ${CODE}
	, ${COL_TYPE}
	, ${NOT_NULL}
	, ${COL_FORMAT}
	, ${COL_ALIGN}
	, ${COL_SORT}
	, ${COL_COLOR}
	, ${COL_SEQ}
	, ${session.ID}
	, ${current.DATE}
	, ${current.TIME}
	, ${session.ID}
	, ${current.DATE}
	, ${current.TIME}
)


    	INSERT INTO SMUFP
    	(
    		  HOUSE_CODE
    		, MENU_PROFILE_CODE
    		, MENU_ID
    		, ADD_USER_ID
    		, ADD_DATE
    		, ADD_TIME
    	)
    	VALUES
    	(
	    	  ${HOUSE_CODE}
    		, ${MENU_PROFILE_CODE}
    		, ${MENU_ID}
    		, ${session.ID}
    		, ${current.DATE}
    		, ${current.TIME}	
    	)


INSERT INTO SCMAM
(
	  HOUSE_CODE
	, MODULE
	, OPTIONS
)
VALUES
(
	  ${HOUSE_CODE}
	, ${MODULE}
	, ${OPTIONS}
)


    	INSERT INTO SLANG
		(
			  HOUSE_CODE
			, SCREEN_ID
			, `LANGUAGE`
			, CODE
			, CONTENTS
			, GRID_WIDTH
			, FORM_WIDTH
			, ADD_USER_ID
			, ADD_DATE
			, ADD_TIME
			, CHANGE_USER_ID
			, CHANGE_DATE
			, CHANGE_TIME
			, DEL_FLAG
		)
		VALUES
		(
			  ${HOUSE_CODE}
			, ${SCREEN_ID}
			, ${LANGUAGE}
			, ${CODE}
			, #DB_OWNER#NVL(${CONTENTS}, NULL)
			, #DB_OWNER#NVL(${GRID_WIDTH}, NULL)
			, #DB_OWNER#NVL(${FORM_WIDTH}, NULL)
			, ${session.ID}
			, ${current.DATE}
			, ${current.TIME}
			, ${session.ID}
			, ${current.DATE}
			, ${current.TIME}
			, #DB_OWNER#NVL(${DEL_FLAG}, NULL)
		)
